(()=>{'use strict';renderPrototypeNav('lab');const groups=window.PROJECT_GROUPS;const titles=[['Semiconductor','Research'],['Applied AI','& Manufacturing'],['Beyond','the Fab']];const descriptions=['芯片、算力与制造机会。','从设备信号到实际工作流。','工作之外，继续保持好奇。'];document.querySelector('#research-panels').innerHTML=groups.map((g,i)=>`<section class="lab-panel lab-project" data-category="${i}" aria-labelledby="chapter-${i}"><div class="lab-project-head"><p class="eyebrow">SELECTED PROJECTS<span>0${i+1} / ${g.links.length} PROJECTS</span></p><div class="chapter-number" aria-hidden="true">0${g.links.length}</div><h2 id="chapter-${i}">${titles[i].map(t=>`<span>${t}</span>`).join('')}</h2><p class="project-chinese">${g.zh}</p><p>${descriptions[i]}</p></div><div class="lab-project-list">${g.links.map((p,n)=>`<a href="${p.href}" target="_blank" rel="noopener"><span>${String(n+1).padStart(2,'0')}</span><div><h3>${p.title.zh}</h3><p>${p.description.zh}</p></div><span aria-hidden="true">↗</span></a>`).join('')}</div></section>`).join('');document.querySelector('.lab-bio').textContent=window.PROTOTYPE_CONTENT.intro;document.querySelector('.education').innerHTML=window.PROTOTYPE_CONTENT.education;
const stage=document.querySelector('.lab-stage'),sticky=document.querySelector('.lab-sticky'),track=document.querySelector('.lab-panels'),panels=[...document.querySelectorAll('.lab-panel')],canvas=document.querySelector('#wafer-field'),ctx=canvas.getContext('2d'),nav=document.querySelector('.prototype-nav');let w=0,h=0,bar=0,current=0,progress=0,field=0,mobile=false,raf=0,phase=0,lastTime=0,pointer={x:0,y:0},smooth={x:0,y:0};
function resize(){mobile=matchMedia('(max-width:760px)').matches;bar=nav.offsetHeight;document.querySelector('.field-controls p').textContent=mobile?'轻点切换图形，向下浏览项目。':'移动鼠标探索，向下滚动进入项目。';document.documentElement.style.setProperty('--bar-height',bar+'px');w=innerWidth;h=mobile?document.querySelector('.lab-intro').offsetHeight:sticky.offsetHeight;const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);canvas.style.height=h+'px';ctx?.setTransform(dpr,0,0,dpr,0,0);stage.style.height=mobile?'auto':h*panels.length+'px';onScroll();draw();}
function onScroll(){if(mobile){current=panels.reduce((best,p,i)=>Math.abs(p.getBoundingClientRect().top-bar)<Math.abs(panels[best].getBoundingClientRect().top-bar)?i:best,0);progress=current/(panels.length-1);}else{const travel=stage.offsetHeight-sticky.offsetHeight;progress=Math.max(0,Math.min(1,(bar-stage.getBoundingClientRect().top)/travel));current=Math.round(progress*(panels.length-1));track.style.transform=`translate3d(${-progress*(panels.length-1)*w}px,0,0)`;}document.querySelector('.chapter-counter').textContent=String(current+1).padStart(2,'0')+' / 05';document.querySelector('.lab-progress span').style.width=((current+1)/panels.length*100)+'%';document.querySelectorAll('[data-step]').forEach(b=>b.disabled=Number(b.dataset.step)<0?current===0:current===panels.length-1);document.querySelector('.lab-bottom').style.color=(!mobile&&progress<.1)?'#fff':'#141713';if(!raf)draw();}
function go(index){const next=Math.max(0,Math.min(panels.length-1,index)),behavior=document.body.dataset.motion==='off'?'instant':'smooth';if(mobile){window.scrollTo({top:scrollY+panels[next].getBoundingClientRect().top-bar,behavior});}else{const start=scrollY+stage.getBoundingClientRect().top-bar,travel=stage.offsetHeight-sticky.offsetHeight;window.scrollTo({top:start+next/(panels.length-1)*travel,behavior});}}
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(Number(b.dataset.go))));document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>go(current+Number(b.dataset.step))));document.querySelectorAll('[data-field]').forEach(b=>b.addEventListener('click',()=>{field=Number(b.dataset.field);document.querySelectorAll('[data-field]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw();}));track.addEventListener('focusin',e=>{if(mobile)return;const p=e.target.closest('.lab-panel'),index=panels.indexOf(p);if(index>=0&&Math.abs(index-progress*(panels.length-1))>.2)go(index);});
sticky.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=sticky.getBoundingClientRect();pointer.x=(e.clientX-r.left)/w-.5;pointer.y=(e.clientY-r.top)/h-.5;});sticky.addEventListener('pointerleave',()=>{pointer.x=0;pointer.y=0;});
function disc(x,y,r,angle,tone){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle=tone;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.clip();ctx.strokeStyle=field===2?'#f05b3922':'#eeeeee16';ctx.lineWidth=.8;const cell=field===1?Math.max(28,r*.23):Math.max(24,r*.16);for(let a=-r;a<=r;a+=cell){for(let b=-r;b<=r;b+=cell){if(a*a+b*b>r*r)continue;if(field===1){ctx.fillStyle='#efeee617';ctx.fillRect(a+3,b+3,cell-6,cell-6);}else if(field===2){ctx.beginPath();ctx.moveTo(a,b);ctx.lineTo(a+cell*.7,b);ctx.lineTo(a+cell*.7,b+cell*.7);ctx.lineTo(a+cell,b+cell*.7);ctx.stroke();}else{ctx.strokeRect(a+1,b+1,cell-2,cell-2);}}}ctx.restore();}
function draw(){if(!ctx||!w||!h)return;const transition=mobile?0:Math.min(1,progress*6),start=[233,79,45],end=[240,238,229];ctx.fillStyle=`rgb(${start.map((v,i)=>Math.round(v+(end[i]-v)*transition)).join(',')})`;ctx.fillRect(0,0,w,h);const mx=smooth.x,my=smooth.y,t=phase,unit=Math.min(w,h);const tone=transition>.5?['#7460b2','#3a604c','#202222'][Math.min(2,Math.max(0,current-1))]:'#111314';disc(w*.69+mx*80+Math.sin(t*.3)*unit*.025,h*.24+my*60,unit*.41,t*.06,tone);disc(w*1.04-mx*60,h*.81-my*50,unit*.32,-t*.08,tone);disc(w*.30+mx*30,h*1.1,unit*.2,t*.1,tone);for(let i=0;i<12;i++){const angle=i*.68+t*.045;const x=w*.78+Math.cos(angle)*unit*.4-mx*15,y=h*.42+Math.sin(angle)*unit*.52-my*15;ctx.fillStyle=tone;ctx.beginPath();ctx.arc(x,y,unit*(.012+(i%4)*.009),0,Math.PI*2);ctx.fill();}}
function tick(time){raf=0;if(document.body.dataset.motion!=='on')return;if(time-lastTime>30){smooth.x+=(pointer.x-smooth.x)*.09;smooth.y+=(pointer.y-smooth.y)*.09;phase+=.017;if(!mobile||canvas.getBoundingClientRect().bottom>0)draw();lastTime=time;}raf=requestAnimationFrame(tick);}
function motionChanged(){if(raf)cancelAnimationFrame(raf);raf=0;draw();if(document.body.dataset.motion==='on')raf=requestAnimationFrame(tick);}window.addEventListener('motionchange',motionChanged);window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',resize);document.addEventListener('visibilitychange',()=>{if(document.hidden){if(raf)cancelAnimationFrame(raf);raf=0;}else motionChanged();});resize();motionChanged();
})();
